    ctx.fillStyle = '#ff3b30';
    ctx.fillRect(-L * 0.02, -Wid * 0.32, L * 0.1, Wid * 0.28);
    ctx.fillStyle = '#2e7df2';
    ctx.fillRect(-L * 0.02, Wid * 0.05, L * 0.1, Wid * 0.28);
