function drawMarker(ctx, S, W, H) {
  const m = S.mission;
  if (!m || !m.target) return;
  const t = m.target;
  const c = projectPoint(S, W, H, t.x, t.z);
  const s = c.scale;
  const pulse = 0.5 + 0.5 * Math.sin(S.time * 3);
  ctx.fillStyle = `rgba(255, 217, 74, ${0.25 + pulse * 0.2})`;
