function drawLooseCash(ctx, S, W, H) {
  for (const c of S.looseCash) {
    const p = projectPoint(S, W, H, c.x, c.z);
    ctx.fillStyle = '#2fae4e';
    ctx.beginPath(); ctx.arc(p.x, p.y, 5 * p.scale, 0, Math.PI * 2); ctx.fill();
