}

function drawPalm(ctx, S, W, H, palm) {
  const c = projectPoint(S, W, H, palm.x, palm.z);
  const s = c.scale;
  ctx.strokeStyle = '#7a5c33';
  ctx.lineWidth = 2.5 * s;
